layers.vertex:
attribute vec3 aO, aE; attribute float aT; uniform float uTime; varying vec2 vP; varying float vU; vec3 arcAt(vec3 a, vec3 b, float f){
    vec3 d = b - a; vec3 side = normalize(cross(d, vec3(0., 1., 0.))); float e = sin(3.14159*f);
    return mix(a, b, f) + side*.11*sin(f*9.)*e + vec3(0., .035*sin(f*13. + 1.), 0.)*e; }
    void main(){
      float u = uTime - aT - 0.10, L = length(aE - aO), tt = L/5.0;
      if (u < 0. || u > tt){ gl_Position = vec4(2.,2.,2.,1.); return; }
      vec4 mv = viewMatrix*vec4(arcAt(aO, aE, u/tt), 1.); mv.xyz += normalize(-mv.xyz)*.05; float S = .78;
      float c = cos(u*4.33), s = sin(u*4.33); vec2 q = mat2(c, -s, s, c)*position.xy;   // corona turns with the arms (same angular speed)
      mv.xy += q*S*1.2; vP = position.xy; vU = u; gl_Position = projectionMatrix*mv;
    }

layers.fragment:
uniform vec3 uGold, uOrange; varying vec2 vP; varying float vU;
    void main(){                                              // astral star: 4 long points + 4 short, bright core, soft halo
      vec2 p = vP; float r = length(p), a = atan(p.y, p.x);
      float fl = .5 + .5*sin(a*7. + vU*40.)*sin(a*3. - vU*23.);             // flickering flame tongues
      float sphere = smoothstep(.34, .28, r), corona = exp(-pow(max(r - .3, 0.)/(.07 + .09*fl), 2.))*step(.28, r);
      float core = exp(-r*r*40.), halo = exp(-r*r*5.)*.2;
      vec3 o = (uOrange*(corona*.9 + halo*.6 + sphere*.45) + uGold*sphere*.25*(.6 + .4*fl) + vec3(1., .6, .2)*core*.4)*smoothstep(1., .85, r);   // fire core: saturated orange-red, small hot centre, see-through
      if (max(o.r, max(o.g, o.b)) < .002) discard; gl_FragColor = vec4(o, 1.); }

layers.vertex:
attribute vec3 aO, aE; attribute float aT, aM; attribute vec4 aP; uniform float uTime;
    varying vec2 vQ; varying float vAge, vHeat, vSeed; vec3 arcAt(vec3 a, vec3 b, float f){
    vec3 d = b - a; vec3 side = normalize(cross(d, vec3(0., 1., 0.))); float e = sin(3.14159*f);
    return mix(a, b, f) + side*.11*sin(f*9.)*e + vec3(0., .035*sin(f*13. + 1.), 0.)*e; } float eox(float x){ return x >= 1. ? 1. : 1. - pow(2., -10.*x); }
    void main(){
      float L = length(aE - aO), tt = L/5.0, u = uTime - aT - 0.10;
      vec3 P, Pn = vec3(0.); float size, age, heat, stretch = 0.;
      if (aM < 1.5){
        if (u < 0. || u > tt){ gl_Position = vec4(2.,2.,2.,1.); return; }
        vec3 d = (aE - aO)/L, sd = normalize(cross(d, vec3(0., 1., 0.)));
        vec3 C = arcAt(aO, aE, u/tt);
        vec3 n = normalize(vec3(0., 1., 0.) + normalize(cameraPosition - C)*.4 + sd*.07*sin(u*5.2) + d*.045*sin(u*3.7 + 1.));
        vec3 e1 = normalize(cross(n, d)), e2 = cross(e1, n);
        float grow = 1. - pow(1. - clamp(u/.15, 0., 1.), 3.), spin = u*26.;
        float life = .3 + .15*aP.z;
        if (aM < .5){                                                          // ARM flame: evenly spaced along its arm, flowing slowly outwards
          age = fract(aP.y + u*.9);                                            // 0 = at the core, 1 = at the tip (then it re-enters at the core)
          float r = mix(.2, 1., age)*1.43, a = aP.x*6.28318 + spin/6. - 2.5*r/1.43 + (aP.w - .5)*.35;   // loose flames scattered around the arm (aP.x = arm/6)
          P = C + (e1*cos(a) + e2*sin(a))*r*grow + n*(.02 + .1*age*age) + vec3(0., .06*age, 0.);
          float r2 = r + .08, a2 = a - 2.5*.08/1.43;
          Pn = C + (e1*cos(a2) + e2*sin(a2))*r2*grow;                          // next point along the arm: flame stretches along it, tip outwards
          size = (.16 - .07*age)*(.85 + .3*aP.w)*grow;                            // thick near the ball, thinner to the tip
          heat = 1.05 - .6*age;                                                  // hot at the root, cooler and smokier at the tip
        } else {                                                               // (unused: the core is the fire-ball billboard)
          age = fract(u/life + aP.y);
          float a = aP.x*6.28318 + spin*.35, r = .18*sqrt(aP.w)*(1. + .5*age);
          P = C + (e1*cos(a) + e2*sin(a))*r + vec3(0., .25*age, 0.) + n*.05*sin(aP.w*20.);
          size = (.2 + .12*aP.w)*(1. - .35*age)*grow;
          heat = 1.1 - age;
        }
      } else {                                                                 // impact burst: radial, once, then smoke rising
        age = (u - tt - aP.z*.05)/(.55 + .3*aP.w); if (age < 0. || age > 1.){ gl_Position = vec4(2.,2.,2.,1.); return; }
        float th = aP.x*6.28318, ph = (aP.y - .5)*2.2;
        vec3 dir = vec3(cos(th)*cos(ph), sin(ph)*.7 + .25, sin(th)*cos(ph));
        P = aE + dir*(.2 + 1.1*eox(age)) + vec3(0., .5*age*age, 0.);
        size = (.22 + .45*age)*(.8 + .4*aP.w);
        heat = 1.1 - age*1.1;
      }
      vec4 mv = viewMatrix*vec4(P, 1.);
      vec2 q = position.xy*2.;
      if (stretch > .5){                                                       // arm flame: long axis along the arm (screen space), tongue tip outward
        vec4 mn = viewMatrix*vec4(Pn, 1.); vec2 ax = mn.xy - mv.xy; ax = length(ax) > 1e-4 ? normalize(ax) : vec2(0., 1.);
        vec2 px = vec2(-ax.y, ax.x);
        mv.xy += (ax*q.y*2.3 + px*q.x*.8)*size;
      } else {
        float rot = (aP.y - .5)*.6;
        q = vec2(cos(rot)*q.x - sin(rot)*q.y, sin(rot)*q.x + cos(rot)*q.y);
        mv.xy += q*size*vec2(.8, 1.1);                                          // a little taller than wide: flame
      }
      vQ = position.xy*2.; vAge = age; vHeat = heat; vSeed = aP.y;
      gl_Position = projectionMatrix*mv;
    }

layers.fragment:
uniform float uTime; varying vec2 vQ; varying float vAge, vHeat, vSeed;
    float h(vec2 p){ return fract(sin(dot(p, vec2(127.1, 311.7)))*43758.5); }
    float vn(vec2 p){ vec2 i = floor(p), f = fract(p); f = f*f*(3. - 2.*f);
      return mix(mix(h(i), h(i + vec2(1., 0.)), f.x), mix(h(i + vec2(0., 1.)), h(i + vec2(1., 1.)), f.x), f.y); }
    void main(){
      vec2 q = vQ; float t = uTime*2.2 + vSeed*17.;
      // domain-warped flame: noise pushes the shape around and tears the edges; tongue narrows towards the top
      vec2 w = vec2(vn(q*1.8 + vec2(0., -t*1.6) + vSeed*9.), vn(q*1.8 + vec2(5.2, -t*1.3) + vSeed*4.)) - .5;
      vec2 p = q + w*.7;
      float d = length(vec2(p.x*(1.15 + .55*max(p.y, 0.)), (p.y + .1)*.85));
      float n = vn(p*3.2 + vec2(0., -t*2.4) + vSeed*3.)*.65 + vn(p*6.5 + vec2(0., -t*3.5))*.35;
      float dens = smoothstep(1., .15, d)*smoothstep(.15, .6, n + (1. - d)*.55);
      dens *= smoothstep(1., .75, vAge)*smoothstep(0., .06, vAge);
      dens *= smoothstep(1., .7, length(q))*smoothstep(1., .85, max(abs(q.x), abs(q.y)));   // reach zero before the quad edge (no visible rotated square)
      // temperature ramp: white-yellow core → orange → deep red → dark smoke
      float T = clamp(vHeat*(.4 + .5*(1. - d))*(.8 + .4*n), 0., 1.05);
      // saturated fire ramp (refs): smoke → deep red → strong orange → yellow-orange; pale yellow only in the hottest thin veins
      vec3 smoke = vec3(.012, .008, .006), red = vec3(.42, .025, .004), org = vec3(1., .22, .015), yel = vec3(1., .5, .06), wht = vec3(1., .8, .38);
      vec3 col = T < .25 ? mix(smoke, red, T/.25) : T < .55 ? mix(red, org, (T - .25)/.3) : T < .85 ? mix(org, yel, (T - .55)/.3) : mix(yel, wht, clamp((T - .85)/.3, 0., 1.));
      float emit = T < .25 ? .08 : .4*T;                                      // per-flame light kept low: hundreds overlap                                      // cold = no light (smoke), hot = emissive
      float alpha = dens*mix(.35, .08, clamp(T/.6, 0., 1.));                   // smoke occludes, hot flame mostly adds
      vec3 rgb = col*emit*dens;
      if (dens < .003){ discard; }
      gl_FragColor = vec4(rgb, alpha);
    }

layers.vertex:
attribute vec3 aO, aE; attribute float aT; attribute vec2 aP; uniform float uTime; varying vec2 vS; varying float vU; vec3 arcAt(vec3 a, vec3 b, float f){
    vec3 d = b - a; vec3 side = normalize(cross(d, vec3(0., 1., 0.))); float e = sin(3.14159*f);
    return mix(a, b, f) + side*.11*sin(f*9.)*e + vec3(0., .035*sin(f*13. + 1.), 0.)*e; }
    vec3 armAt(float s, vec3 C, vec3 e1, vec3 e2, vec3 n, float spin, float grow){
      float r = mix(.06, 1., s)*1.43, a = aP.x*6.28318 + spin/6. - 2.5*r/1.43;   // roots start inside the ball
      return C + (e1*cos(a) + e2*sin(a))*r*grow + n*.06*s*s;
    }
    void main(){
      float L = length(aE - aO), tt = L/5.0, u = uTime - aT - 0.10;
      if (u < 0. || u > tt){ gl_Position = vec4(2.,2.,2.,1.); return; }
      vec3 d = (aE - aO)/L, sd = normalize(cross(d, vec3(0., 1., 0.)));
      vec3 C = arcAt(aO, aE, u/tt);
      vec3 n = normalize(vec3(0., 1., 0.) + normalize(cameraPosition - C)*.4 + sd*.07*sin(u*5.2) + d*.045*sin(u*3.7 + 1.));
      vec3 e1 = normalize(cross(n, d)), e2 = cross(e1, n);
      float grow = 1. - pow(1. - clamp(u/.15, 0., 1.), 3.), spin = u*19.;
      float s = position.x + .5;
      vec3 P = armAt(s, C, e1, e2, n, spin, grow), T = normalize(armAt(min(s + .02, 1.), C, e1, e2, n, spin, grow) - armAt(max(s - .02, 0.), C, e1, e2, n, spin, grow));
      vec3 side = normalize(cross(n, T));                                       // width lies in the disc plane
      float w = 1.43*(.3 - .23*pow(s, .7))*(.25 + .75*smoothstep(0., .2, s))*grow;   // thick at the base, narrow tip; root pinches in (no straight cut)
      gl_Position = projectionMatrix*viewMatrix*vec4(P + side*position.y*2.*w, 1.);
      vS = vec2(s, position.y*2.); vU = u + aP.y*7.;
    }

layers.fragment:
varying vec2 vS; varying float vU;
    float h(vec2 p){ return fract(sin(dot(p, vec2(127.1, 311.7)))*43758.5); }
    float vn(vec2 p){ vec2 i = floor(p), f = fract(p); f = f*f*(3. - 2.*f);
      return mix(mix(h(i), h(i + vec2(1., 0.)), f.x), mix(h(i + vec2(0., 1.)), h(i + vec2(1., 1.)), f.x), f.y); }
    void main(){
      float s = vS.x, y = vS.y, t = vU;
      // flame texture flowing outward along the arm; the trailing edge (y > 0) tears into licks
      float n1 = vn(vec2(s*3.5 - t*2.2, y*2. + t*.4)), n2 = vn(vec2(s*5. - t*3., y*2.5 - t*.6));   // low frequency along the arm: no grain
      float n = n1*.65 + n2*.35;
      float yy = y + (n1 - .5)*.5;                                               // wavy, uneven width
      float body = exp(-yy*yy*(2.2 + 1.5*step(0., yy)));                         // leading edge firmer, trailing edge softer
      float lick = smoothstep(.05, .95, n + .5*(1. - abs(yy)));                 // soft, cloudy edges (no hard tears)                  // torn, flickering edges
      float streak = vn(vec2(s*2. - t*1.6, yy*3.5 + n1*1.2))*.7 + vn(vec2(s*3.5 - t*2.2, yy*6.))*.3;   // long smooth filaments: stretched ALONG the arm
      streak = smoothstep(.05, .95, streak);                                    // wide, blurred bands instead of lines
      float dens = body*lick*(.55 + .45*streak)*smoothstep(1., .72, s)*smoothstep(.02, .22, s)*smoothstep(1., .82, abs(y));
      float T = clamp((1. - .55*s)*(.4 + .6*body*mix(1., streak, .4))*(.9 + .2*n), 0., 1.);   // smooth colour transitions
      // saturated fire ramp (refs): smoke → deep red → strong orange → yellow-orange; pale yellow only in the hottest thin veins
      vec3 smoke = vec3(.012, .008, .006), red = vec3(.42, .025, .004), org = vec3(1., .22, .015), yel = vec3(1., .5, .06), wht = vec3(1., .8, .38);
      vec3 col = T < .25 ? mix(smoke, red, T/.25) : T < .55 ? mix(red, org, (T - .25)/.3) : T < .85 ? mix(org, yel, (T - .55)/.3) : mix(yel, wht, clamp((T - .85)/.3, 0., 1.));
      float emit = T < .25 ? .08 : 1.15*T;
      float alpha = dens*mix(.3, .06, clamp(T/.6, 0., 1.));                     // mostly see-through: dark shows between the filaments
      // the arm root takes the ball's outer colour (orange-red corona) and blends into the arm's own ramp as it leaves the ball
      float root = 1. - smoothstep(.15, .45, s);
      col = mix(col, vec3(1., .16, .02), root*.85); emit = mix(emit, .75, root*.6);
      float glow = exp(-y*y*2.5)*smoothstep(1., .55, s)*smoothstep(.04, .26, s)*smoothstep(1., .85, abs(y))*(1. - .5*s);   // soft glow hugging the arm
      vec3 g = mix(vec3(1., .22, .02), vec3(1., .45, .06), 1. - s)*glow*.3;
      if (dens < .003 && glow < .003){ discard; }
      gl_FragColor = vec4(col*emit*dens + g, alpha);
    }

layers.vertex:
attribute vec3 aO; attribute float aT, aK; attribute vec4 aD; uniform float uTime; varying vec2 vP; varying float vU, vK;
    void main(){ float u = uTime - aT; if (u < 0. || u > 1.00){ gl_Position = vec4(2.,2.,2.,1.); return; }
      vU = u; vK = aK; vP = position.xy;
      if (aK > 4.5){                                          // push streak: flat on the ground from the hit point along the push
        vec3 dir = vec3(aD.x, 0., aD.y); vec3 nrm = vec3(-dir.z, 0., dir.x);
        float s = position.x*.5 + .5; vP = vec2(s, position.y);
        gl_Position = projectionMatrix*viewMatrix*vec4(aO + dir*s*aD.z + nrm*position.y*.22 + vec3(0., .03, 0.), 1.); return; }
      if (aK > 2.5){                                          // Weave: a resource mote flies back to the caster on a curved path
        float k = clamp((u - aD.w)/.45, 0., 1.); if (u < aD.w || k >= 1.){ gl_Position = vec4(2.,2.,2.,1.); return; }
        float e = k*k*(3. - 2.*k); vec3 A = aO + vec3(0., 1.2, 0.), B = aD.xyz;
        vec3 side = normalize(cross(B - A, vec3(0., 1., 0.)))*sin(aD.w*37.)*.8;
        vec3 P = mix(A, B, e) + (side + vec3(0., .9, 0.))*sin(3.14159*e);
        vec4 mv = viewMatrix*vec4(P, 1.); float S = .09; mv.xy += position.xy*S; vU = k; gl_Position = projectionMatrix*mv; return; }
      if (aK < .5){ float S = .95; vP = position.xy*S; gl_Position = projectionMatrix*viewMatrix*vec4(aO + vec3(position.x*S, .03, -position.y*S), 1.); }
      else if (aK < 1.5){ vec4 mv = viewMatrix*vec4(aO + vec3(0., 1.25, 0.), 1.); mv.xyz += normalize(-mv.xyz)*.32; mv.xy += position.xy*vec2(.26, .3); gl_Position = projectionMatrix*mv; }
      else { vec4 mv = viewMatrix*vec4(aO + vec3(0., 1.2, 0.), 1.); mv.xyz += normalize(-mv.xyz)*.3; float S = .75; mv.xy += position.xy*S; vP = position.xy*S; gl_Position = projectionMatrix*mv; }
    }

layers.fragment:
uniform vec3 uGold, uOrange; varying vec2 vP; varying float vU, vK; float lcore(float d, float w){ return exp(-(d*d)/(w*w)); }
    float h1(float n){ return fract(sin(n*91.7)*43758.5); }
    void main(){
      float lum = 0., hot = 0., t = vU/1.00;
      if (vK > 4.5){                                          // scorch streak: grows with the slide (ease-out), bright at the leading end, fades
        float k = 1. - pow(1. - clamp(vU/.35, 0., 1.), 3.), s = vP.x, y = vP.y;
        float lead = exp(-pow((s - k)/.06, 2.)), body = smoothstep(k + .02, k - .05, s)*(.35 + .65*s);
        float f = (1. - smoothstep(.35, .75, vU))*smoothstep(0., .03, s);
        float w = exp(-y*y*(10. + 10.*(1. - s)));
        vec3 o = (uOrange*(body*.5 + lead*.8) + mix(uGold, vec3(1.), .4)*lead*.5)*w*f*smoothstep(1., .75, abs(y));
        if (max(o.r, max(o.g, o.b)) < .002) discard; gl_FragColor = vec4(o, 1.); return;
      }
      if (vK < .5){
        float r = length(vP), e = pow(clamp(vU/.25, 0., 1.), 3.), R = .8 - .65*e, f = (vU < .033 ? 1.5 : 1.)*(1. - smoothstep(.55, 1., t));
        lum += exp(-pow(abs(r - R)/.016, 2.4))*f; hot += lcore(r - R, .005)*f*.6;
        lum *= smoothstep(.95, .85, r); hot *= smoothstep(.95, .85, r);
      } else if (vK < 1.5){
        // Manifest · Burn mark: a small flame sigil held on the target after the impact (brief, then the status cue takes over)
        float x = vP.x, y = vP.y*.5 + .5, t = clamp((vU - .2)/.6, 0., 1.);
        vec2 q = vec2(x*2.2, (y - .55)*4.6); float r = length(q);
        float flame = smoothstep(.55, .45, length(vec2(q.x*(1.3 + q.y*.5), q.y + .2)))*smoothstep(-.9, -.4, q.y)*(1. - smoothstep(.55, 1.1, q.y + .1*sin(vU*30.)));
        float edge = flame*(1. - smoothstep(.3, .45, length(vec2(q.x*(1.3 + q.y*.5), q.y + .2))));
        float f = step(.2, vU)*(vU < .233 ? 1.8 : 1.)*(1. - smoothstep(.55, 1., t));
        lum += (flame - edge*.7)*f*1.1; hot = edge*f*.2;
        lum *= smoothstep(1., .75, abs(x)); hot *= smoothstep(1., .75, abs(x));
      } else {
        if (vK > 2.5){ float r = length(vP); float m = exp(-r*r*8.)*(1. - vU)*1.6;       // Weave mote
          vec3 o = uGold*m + vec3(1., .95, .8)*exp(-r*r*40.)*(1. - vU);
          if (max(o.r, max(o.g, o.b)) < .002) discard; gl_FragColor = vec4(o, 1.); return; }
