        float r = length(vP), a = atan(vP.y, vP.x), t2 = clamp(vU/.35, 0., 1.);
        float R = .12 + .25*(1. - pow(1. - t2, 3.)), fl = .5 + .5*sin(a*9. + 2.)*sin(a*4. - 1.);
        float body = exp(-r*r*(30. + 50.*t2))*(vU < .033 ? 2. : 1.4*(1. - t2));
        float tongues = pow(max(0., cos(a*6.))*fl, 2.)*smoothstep(R + .18*fl, R, r)*smoothstep(.05, .15, r)*(1. - t2);
        float rim = exp(-pow((r - R)/.03, 2.))*(1. - t2)*.8;
        lum += body + tongues*1.2 + rim; hot = body*.7 + exp(-r*r*150.)*(1. - t2);
        lum *= smoothstep(.75, .62, r); hot *= smoothstep(.75, .62, r);
      }
      vec3 o = uOrange*lum + mix(uGold, vec3(1.), .5)*hot;
      if (max(o.r, max(o.g, o.b)) < .002) discard;
      gl_FragColor = vec4(o, 1.);
    }
